insert into compliance_flag (id, job_book_id, rule_id, severity, title, detail, section_number, fingerprint, state, due_at) values
  ('d0d0d0d0-3f4d-397e-1619-f4d916eaabf6', 'd0d0d0d0-e488-17c7-c197-6ed6e2c656b2', 'section.empty_required', 'critical', '2 required sections are empty', 'This section is required by the governing checklist and holds no documents or records. It carries 8 weight points, and the book cannot be turned over without it. This is the first of 2; open the finding for the full list.', '17', 'section.empty_required|group', 'open', '2026-09-26'),
  ('d0d0d0d0-88d0-3a56-1914-f3eff8516d1c', 'd0d0d0d0-e488-17c7-c197-6ed6e2c656b2', 'timeliness.below_target', 'warning', 'Entry Timeliness Rate is 50%, below the 95% target', '3 of 6 measurable entries met their §8.1 standard. §8.3 escalates a book below 90% for two consecutive weeks to the Project Manager and the VP of Operations.', '12', 'timeliness.below_target', 'open', '2026-10-12'),
  ('d0d0d0d0-8b7a-43b2-454d-a1bfe52ed88a', 'd0d0d0d0-e488-17c7-c197-6ed6e2c656b2', 'document.filename_normalized', 'info', '19 files were renamed to the book''s filing convention', 'The uploaded name did not follow the book''s filing convention and was normalized. The original name is preserved on the record. This is the first of 19; open the finding for the full list.', null, 'document.filename_normalized|group', 'open', '2026-10-13'),
  ('d0d0d0d0-c5d4-cf0c-3f52-bfd757603cc3', 'd0d0d0d0-e488-17c7-c197-6ed6e2c656b2', 'timeliness.late_entry', 'info', 'Weld W-0001 was entered 3 business days past its standard', 'Work dated 2026-08-17, due in the book by 2026-08-18 under FDS-JBMP-001 §8.1, entered 2026-08-21. The record stands as entered — §8.3 requires a late entry to be accurate and flagged, never back-dated. This is the first of 3; open the finding for the full list.', '12', 'timeliness.late_entry|group', 'open', '2026-10-14')
