  ('d0d0d0d0-4a86-2c3d-0f73-5db516055857', 'd0d0d0d0-11c4-9d67-0910-4f8296208107', 'document.filename_normalized', 'info', '21 files were renamed to the book''s filing convention', 'The uploaded name did not follow the book''s filing convention and was normalized. The original name is preserved on the record. This is the first of 21; open the finding for the full list.', null, 'document.filename_normalized|group', 'open', '2026-10-13'),
  ('d0d0d0d0-d61c-7aac-0e14-49c1ad29d262', 'd0d0d0d0-11c4-9d67-0910-4f8296208107', 'timeliness.late_entry', 'info', 'Weld W-0001 was entered 3 business days past its standard', 'Work dated 2026-04-06, due in the book by 2026-04-07 under FDS-JBMP-001 §8.1, entered 2026-04-10. The record stands as entered — §8.3 requires a late entry to be accurate and flagged, never back-dated. This is the first of 4; open the finding for the full list.', '12', 'timeliness.late_entry|group', 'open', '2026-10-14')
