  ('d0d0d0d0-1e82-1407-afda-e75fe247c065', 'd0d0d0d0-2648-2e52-3c34-3503849e89c1', 'G1', 1, 'pass', 'd0d0d0d0-3d06-5afb-2e08-226c18716b69', 'd0d0d0d0-3c78-d035-c5f5-a6ba1b49cce7', null, '2025-05-08T17:00:00Z', '[{"id":"g1.curve","gate":"G1","text":"Weighted completion at or above the planned curve.","source":"derived","state":"met","detail":"Weighted completion 93.64% against a planned 25%."},{"id":"g1.timeliness","gate":"G1","text":"Entry timeliness rate at or above 95% for the period.","source":"derived","state":"met","detail":"Entry Timeliness Rate 96.51% over 86 measurable entries, against a 95% target."},{"id":"g1.self_audit","gate":"G1","text":"All scheduled Tier 1 self audits performed, signed and on file.","source":"derived","state":"indeterminate","detail":"The Tier 1 self-audit schedule of §10 is not yet implemented in the application."},{"id":"g1.peer_audit","gate":"G1","text":"First Tier 2 peer audit performed, scored at 90 or above, with zero Critical findings.","source":"derived","state":"indeterminate","detail":"No Tier 2 peer audit is recorded for this book. The three-tier audit model of §10 is not yet implemented in the application."},{"id":"g1.registers","gate":"G1","text":"Controlled registers populated: welders, wrenches, heats, isometric drawings.","source":"derived","state":"met","detail":"Welders 6, wrenches 4, heats 9. The isometric drawing register is not yet modelled in the application, so that fourth register is the chair’s to confirm."},{"id":"g1.heats","gate":"G1","text":"Heat register reconciled. Every heat referenced by a weld has an MTR on file.","source":"derived","state":"met","detail":"All 9 heats referenced by welds have an MTR on file."},{"id":"g1.ncr","gate":"G1","text":"Zero open NCRs past due date.","source":"derived","state":"met","detail":"No open Critical or Major findings."}]', 93.64, 'Demo book. 2 criteria unmet or unevaluable at the time of review; passed on the strength of the Tier 2 audit and the Custodian''s action list.', null),
  ('d0d0d0d0-a070-6ef8-87fb-212c7f5c51ea', 'd0d0d0d0-2648-2e52-3c34-3503849e89c1', 'G2', 1, 'pass', 'd0d0d0d0-3d06-5afb-2e08-226c18716b69', 'd0d0d0d0-3c78-d035-c5f5-a6ba1b49cce7', null, '2025-07-07T17:00:00Z', '[{"id":"g2.gate1_sustained","gate":"G2","text":"All Gate 1 criteria, sustained.","source":"derived","state":"indeterminate","detail":"2 Gate 1 criteria cannot be evaluated: g1.self_audit, g1.peer_audit."},{"id":"g2.curve","gate":"G2","text":"Weighted completion at or above the planned curve.","source":"derived","state":"met","detail":"Weighted completion 93.64% against a planned 50%."},{"id":"g2.iso_stage1","gate":"G2","text":"Isometric markup stage 1 complete for every construction area at mechanical completion.","source":"derived","state":"indeterminate","detail":"The isometric markup register is not yet modelled in the application. Sections 21 and 22 carry no stage, signer or per-area status, so this cannot be evaluated from the book."},{"id":"g2.pressure_closed","gate":"G2","text":"Pressure test packages closed for every test performed to date, including result documents.","source":"derived","state":"met","detail":"All 4 tests performed to date carry a recorded result and a result document."},{"id":"g2.cert_forecast","gate":"G2","text":"Certificate expiry forecast reviewed. No certificate expires inside the remaining work window without a requalification plan on file.","source":"derived","state":"met","detail":"No certificate expires between 2026-09-21 and 2026-08-28."},{"id":"g2.peer_audit","gate":"G2","text":"Tier 2 peer audit scored at 90 or above with zero Critical findings.","source":"derived","state":"indeterminate","detail":"No Tier 2 peer audit is recorded for this book. The three-tier audit model of §10 is not yet implemented in the application."}]', 93.64, 'Demo book. 3 criteria unmet or unevaluable at the time of review; passed on the strength of the Tier 2 audit and the Custodian''s action list.', null),
  ('d0d0d0d0-3c47-8014-34ea-2de49e4854aa', 'd0d0d0d0-2648-2e52-3c34-3503849e89c1', 'G3', 1, 'pass', 'd0d0d0d0-3d06-5afb-2e08-226c18716b69', 'd0d0d0d0-3c78-d035-c5f5-a6ba1b49cce7', null, '2025-09-05T17:00:00Z', '[{"id":"g3.records_entered","gate":"G3","text":"All field records entered. Zero records outstanding.","source":"derived","state":"not_met","detail":"6 section(s) below declared scope: §11 22/25, §12 22/25, §14 18/20, §15 9/10, §18 7/8, §19 7/8."},{"id":"g3.iso_stages","gate":"G3","text":"Isometric markup stages 1 and 2 complete for all areas.","source":"derived","state":"indeterminate","detail":"The isometric markup register is not yet modelled in the application."},{"id":"g3.nde","gate":"G3","text":"All NDE reports received, filed and linked to weld records.","source":"derived","state":"met","detail":"All 6 welds with an NDE method resolve to a filed report."},{"id":"g3.pressure","gate":"G3","text":"All pressure and hydro test packages complete with hold data, result documents and valid on test date instrument certificates.","source":"derived","state":"met","detail":"All 4 test packages carry hold data, a result document and gauge, recorder and PSV certificates valid on the test date."},{"id":"g3.heats","gate":"G3","text":"Heat register fully reconciled in both directions: no installed heat without an MTR, and every MTR on file traceable to an installed heat.","source":"derived","state":"met","detail":"9 installed heats, all with MTRs; no MTR on file is untraceable to an installed heat."},{"id":"g3.coating","gate":"G3","text":"Coating inspection records complete for all areas requiring them, where the section is enabled.","source":"derived","state":"met","detail":"All 3 construction areas carry a coating inspection record."},{"id":"g3.backlog","gate":"G3","text":"Document backlog at zero. Nothing unfiled.","source":"attested","state":"indeterminate","detail":"The application can only see what has been filed into it. A pile of unfiled paper is invisible here by construction, so the Custodian attests to the backlog and the chair accepts or rejects that attestation."}]', 93.64, 'Demo book. 3 criteria unmet or unevaluable at the time of review; passed on the strength of the Tier 2 audit and the Custodian''s action list.', null)
insert into compliance_flag (id, job_book_id, rule_id, severity, title, detail, section_number, fingerprint, state, due_at) values
  ('d0d0d0d0-47c0-8fc8-7e9f-1cfc119e5ec5', 'd0d0d0d0-2648-2e52-3c34-3503849e89c1', 'welder.below_job_nde_requirement', 'critical', '3 welders are below the job''s stated NDE requirement', '3 welds with 0 examinations (0.0%). This job''s stated requirement is 100% visual and 10% NDE — "100% visual & 10% NDE". This is the first of 3; open the finding for the full list.', '12', 'welder.below_job_nde_requirement|group', 'open', '2026-09-26'),
  ('d0d0d0d0-d0f6-9e3f-50c3-42b652212d20', 'd0d0d0d0-2648-2e52-3c34-3503849e89c1', 'weld.no_welder_stamp', 'critical', '3 welds carry no welder stamp', 'No welder is recorded against this weld, so it cannot be attributed, checked against a qualification, or counted in any welder''s inspection percentage. This is the first of 3; open the finding for the full list.', '12', 'weld.no_welder_stamp|group', 'open', '2026-09-26'),
  ('d0d0d0d0-e7e5-dbdc-0fb7-bbd644b15de8', 'd0d0d0d0-2648-2e52-3c34-3503849e89c1', 'certificate.expiring_soon', 'warning', '4 certificates expire within the warning window', 'Certificate WPQ ASME IX for welder d0d0d0d0-fa29-4456-34e2-5966d43678e8 expires 2026-10-22. Work performed after that date will not be covered. This is the first of 4; open the finding for the full list.', null, 'certificate.expiring_soon|group', 'open', '2026-10-13'),
  ('d0d0d0d0-5847-a398-4fdd-22c6ac9f1a4e', 'd0d0d0d0-2648-2e52-3c34-3503849e89c1', 'document.filename_normalized', 'info', '38 files were renamed to the book''s filing convention', 'The uploaded name did not follow the book''s filing convention and was normalized. The original name is preserved on the record. This is the first of 38; open the finding for the full list.', null, 'document.filename_normalized|group', 'open', '2026-10-14'),
  ('d0d0d0d0-e6c2-b691-a0e0-0ae4def8c202', 'd0d0d0d0-2648-2e52-3c34-3503849e89c1', 'timeliness.late_entry', 'info', 'Weld W-0001 was entered 3 business days past its standard', 'Work dated 2025-03-10, due in the book by 2025-03-11 under FDS-JBMP-001 §8.1, entered 2025-03-14. The record stands as entered — §8.3 requires a late entry to be accurate and flagged, never back-dated. This is the first of 3; open the finding for the full list.', '12', 'timeliness.late_entry|group', 'open', '2026-10-15')
