insert into gate_review (id, job_book_id, gate, attempt, outcome, chaired_by, custodian_id, project_manager_id, decided_at, criteria_snapshot, completion_pct, override_note, conditional_due_at) values
  ('d0d0d0d0-9235-2e0c-358e-da1868d02e2e', 'd0d0d0d0-5372-5840-7746-6bcbfe1a7058', 'G0', 1, 'pass', 'd0d0d0d0-3d06-5afb-2e08-226c18716b69', 'd0d0d0d0-3c78-d035-c5f5-a6ba1b49cce7', null, '2025-06-01T17:00:00Z', '[{"id":"g0.scaffolded","gate":"G0","text":"Job book created from the correct template with all applicable sections scaffolded and non applicable sections marked N/A with a recorded reason.","source":"derived","state":"met","detail":"All 21 sections of the flowline template are scaffolded; every N/A section carries a reason."},{"id":"g0.custodian","gate":"G0","text":"Job Book Custodian named in writing and holding competency level JB-2 or above.","source":"derived","state":"met","detail":"Dana Cortez (DEMO) named, competency JB-2."},{"id":"g0.governing_docs","gate":"G0","text":"Client checklist revision and client piping specification revision recorded and confirmed current with the client.","source":"derived","state":"met","detail":"Checklist Operator Turnover Checklist rev C; piping specification Bitterroot Energy Piping Specification rev 4; confirmed with the client 2025-05-27."},{"id":"g0.procedures_loaded","gate":"G0","text":"Section 3 piping specification, Section 4 WPS, Section 5 PQR and Section 9 NDT procedures loaded and legible.","source":"derived","state":"met","detail":"All four procedure sections hold at least one document. Legibility is the chair’s to confirm."},{"id":"g0.wpq","gate":"G0","text":"Section 6 WPQ on file, current, and valid through the planned work window for every welder mobilizing.","source":"derived","state":"met","detail":"All 6 mobilizing welders hold a qualification valid through 2026-05-29."},{"id":"g0.inspector_creds","gate":"G0","text":"Section 7 CWI credentials and Section 8 NDT technician credentials on file and current for every inspector mobilizing.","source":"derived","state":"met","detail":"All 4 mobilizing inspectors hold credentials valid on 2025-06-02."},{"id":"g0.wrench_calibration","gate":"G0","text":"Section 13 calibration certificates on file and current for every torque wrench mobilizing, with each wrench entered in the controlled wrench register.","source":"derived","state":"met","detail":"All 4 registered wrenches hold a calibration valid on 2025-06-02."},{"id":"g0.expected_by","gate":"G0","text":"Section expected by dates set against the construction schedule.","source":"derived","state":"met","detail":"All 20 applicable sections carry an expected-by date."},{"id":"g0.planned_curve","gate":"G0","text":"Planned completion curve agreed and recorded.","source":"derived","state":"met","detail":"Curve agreed 2025-05-27, 6 milestones."}]', 100, null, null),
  ('d0d0d0d0-7ef2-f6cf-a6fa-00be203b4962', 'd0d0d0d0-5372-5840-7746-6bcbfe1a7058', 'G1', 1, 'pass', 'd0d0d0d0-3d06-5afb-2e08-226c18716b69', 'd0d0d0d0-3c78-d035-c5f5-a6ba1b49cce7', null, '2025-07-31T17:00:00Z', '[{"id":"g1.curve","gate":"G1","text":"Weighted completion at or above the planned curve.","source":"derived","state":"met","detail":"Weighted completion 100.00% against a planned 25%."},{"id":"g1.timeliness","gate":"G1","text":"Entry timeliness rate at or above 95% for the period.","source":"derived","state":"met","detail":"Entry Timeliness Rate 95.00% over 60 measurable entries, against a 95% target."},{"id":"g1.self_audit","gate":"G1","text":"All scheduled Tier 1 self audits performed, signed and on file.","source":"derived","state":"indeterminate","detail":"The Tier 1 self-audit schedule of §10 is not yet implemented in the application."},{"id":"g1.peer_audit","gate":"G1","text":"First Tier 2 peer audit performed, scored at 90 or above, with zero Critical findings.","source":"derived","state":"indeterminate","detail":"No Tier 2 peer audit is recorded for this book. The three-tier audit model of §10 is not yet implemented in the application."},{"id":"g1.registers","gate":"G1","text":"Controlled registers populated: welders, wrenches, heats, isometric drawings.","source":"derived","state":"met","detail":"Welders 6, wrenches 4, heats 10. The isometric drawing register is not yet modelled in the application, so that fourth register is the chair’s to confirm."},{"id":"g1.heats","gate":"G1","text":"Heat register reconciled. Every heat referenced by a weld has an MTR on file.","source":"derived","state":"met","detail":"All 10 heats referenced by welds have an MTR on file."},{"id":"g1.ncr","gate":"G1","text":"Zero open NCRs past due date.","source":"derived","state":"met","detail":"No open Critical or Major findings."}]', 100, 'Demo book. 2 criteria unmet or unevaluable at the time of review; passed on the strength of the Tier 2 audit and the Custodian''s action list.', null),
  ('d0d0d0d0-f7f0-bbc9-1a96-d31b437281cd', 'd0d0d0d0-5372-5840-7746-6bcbfe1a7058', 'G2', 1, 'pass', 'd0d0d0d0-3d06-5afb-2e08-226c18716b69', 'd0d0d0d0-3c78-d035-c5f5-a6ba1b49cce7', null, '2025-09-29T17:00:00Z', '[{"id":"g2.gate1_sustained","gate":"G2","text":"All Gate 1 criteria, sustained.","source":"derived","state":"indeterminate","detail":"2 Gate 1 criteria cannot be evaluated: g1.self_audit, g1.peer_audit."},{"id":"g2.curve","gate":"G2","text":"Weighted completion at or above the planned curve.","source":"derived","state":"met","detail":"Weighted completion 100.00% against a planned 50%."},{"id":"g2.iso_stage1","gate":"G2","text":"Isometric markup stage 1 complete for every construction area at mechanical completion.","source":"derived","state":"indeterminate","detail":"The isometric markup register is not yet modelled in the application. Sections 21 and 22 carry no stage, signer or per-area status, so this cannot be evaluated from the book."},{"id":"g2.pressure_closed","gate":"G2","text":"Pressure test packages closed for every test performed to date, including result documents.","source":"derived","state":"met","detail":"All 4 tests performed to date carry a recorded result and a result document."},{"id":"g2.cert_forecast","gate":"G2","text":"Certificate expiry forecast reviewed. No certificate expires inside the remaining work window without a requalification plan on file.","source":"derived","state":"met","detail":"No certificate expires between 2026-06-12 and 2026-05-29."},{"id":"g2.peer_audit","gate":"G2","text":"Tier 2 peer audit scored at 90 or above with zero Critical findings.","source":"derived","state":"indeterminate","detail":"No Tier 2 peer audit is recorded for this book. The three-tier audit model of §10 is not yet implemented in the application."}]', 100, 'Demo book. 3 criteria unmet or unevaluable at the time of review; passed on the strength of the Tier 2 audit and the Custodian''s action list.', null),
  ('d0d0d0d0-a600-a78a-25f8-c76f87242788', 'd0d0d0d0-5372-5840-7746-6bcbfe1a7058', 'G3', 1, 'pass', 'd0d0d0d0-3d06-5afb-2e08-226c18716b69', 'd0d0d0d0-3c78-d035-c5f5-a6ba1b49cce7', null, '2025-11-28T17:00:00Z', '[{"id":"g3.records_entered","gate":"G3","text":"All field records entered. Zero records outstanding.","source":"derived","state":"met","detail":"Every section with a declared scope holds at least the declared number of records."},{"id":"g3.iso_stages","gate":"G3","text":"Isometric markup stages 1 and 2 complete for all areas.","source":"derived","state":"indeterminate","detail":"The isometric markup register is not yet modelled in the application."},{"id":"g3.nde","gate":"G3","text":"All NDE reports received, filed and linked to weld records.","source":"derived","state":"met","detail":"All 6 welds with an NDE method resolve to a filed report."},{"id":"g3.pressure","gate":"G3","text":"All pressure and hydro test packages complete with hold data, result documents and valid on test date instrument certificates.","source":"derived","state":"met","detail":"All 4 test packages carry hold data, a result document and gauge, recorder and PSV certificates valid on the test date."},{"id":"g3.heats","gate":"G3","text":"Heat register fully reconciled in both directions: no installed heat without an MTR, and every MTR on file traceable to an installed heat.","source":"derived","state":"met","detail":"10 installed heats, all with MTRs; no MTR on file is untraceable to an installed heat."},{"id":"g3.coating","gate":"G3","text":"Coating inspection records complete for all areas requiring them, where the section is enabled.","source":"derived","state":"not_applicable","detail":"Section 23 is not enabled for this book."},{"id":"g3.backlog","gate":"G3","text":"Document backlog at zero. Nothing unfiled.","source":"attested","state":"indeterminate","detail":"The application can only see what has been filed into it. A pile of unfiled paper is invisible here by construction, so the Custodian attests to the backlog and the chair accepts or rejects that attestation."}]', 100, 'Demo book. 2 criteria unmet or unevaluable at the time of review; passed on the strength of the Tier 2 audit and the Custodian''s action list.', null),
  ('d0d0d0d0-7c7a-8aff-6f84-4ba83b3e99ef', 'd0d0d0d0-5372-5840-7746-6bcbfe1a7058', 'G4', 1, 'pass', 'd0d0d0d0-3d06-5afb-2e08-226c18716b69', 'd0d0d0d0-3c78-d035-c5f5-a6ba1b49cce7', null, '2026-01-27T17:00:00Z', '[{"id":"g4.complete","gate":"G4","text":"Weighted completion at 100% of applicable, non N/A sections.","source":"derived","state":"met","detail":"Weighted completion is 100%."},{"id":"g4.presence","gate":"G4","text":"100% verification of section presence against the client checklist, item by item, by title.","source":"derived","state":"not_met","detail":"2 of 20 applicable sections are absent, empty or unread: §11, §S1. §10.4 names this the exact failure the Completeness Certification exists to prevent."},{"id":"g4.certificates","gate":"G4","text":"100% verification that every certificate was valid on the date of the work it covers, in both directions.","source":"derived","state":"met","detail":"Every weld, torque and inspection resolves to a certificate valid on the date of the work it covers."},{"id":"g4.peer_audit","gate":"G4","text":"Tier 2 peer audit at double sample size, scored at 95 or above.","source":"derived","state":"indeterminate","detail":"No Tier 2 peer audit is recorded for this book. The three-tier audit model of §10 is not yet implemented in the application."},{"id":"g4.tier3","gate":"G4","text":"Tier 3 QA/QC Manager verification performed and documented.","source":"derived","state":"indeterminate","detail":"No Tier 3 verification is recorded for this book. The three-tier audit model of §10 is not yet implemented in the application."},{"id":"g4.findings","gate":"G4","text":"Zero open Critical findings. Zero open Major findings.","source":"derived","state":"met","detail":"No open Critical or Major findings."},{"id":"g4.export","gate":"G4","text":"Export package generated, table of contents matching the client section numbering, checklist populated to reflect actual status.","source":"attested","state":"indeterminate","detail":"The application generates the export package on demand, so it can always be produced; that a generated package was reviewed against the client numbering is the chair’s to confirm."},{"id":"g4.completeness_cert","gate":"G4","text":"Completeness Certification signed by the QA/QC Manager.","source":"derived","state":"indeterminate","detail":"Form FDS-JB-F07 is not yet implemented in the application. §10.4: \"No job book leaves Fortress without this signature.\""}]', 100, 'Demo book. 5 criteria unmet or unevaluable at the time of review; passed on the strength of the Tier 2 audit and the Custodian''s action list.', null)
