  ('d0d0d0d0-6f9c-c8c7-fe5b-8058da1c99e8', 'd0d0d0d0-5372-5840-7746-6bcbfe1a7058', 'certificate.expiring_soon', 'warning', '2 certificates expire within the warning window', 'Certificate WPQ ASME IX for welder d0d0d0d0-0bb7-aa49-3f3f-36535fd70a03 expires 2026-08-08. Work performed after that date will not be covered. This is the first of 2; open the finding for the full list.', null, 'certificate.expiring_soon|group', 'open', '2026-07-02'),
  ('d0d0d0d0-c7c0-b4de-d43d-94a57467d9b9', 'd0d0d0d0-5372-5840-7746-6bcbfe1a7058', 'document.filename_normalized', 'info', '26 files were renamed to the book''s filing convention', 'The uploaded name did not follow the book''s filing convention and was normalized. The original name is preserved on the record. This is the first of 26; open the finding for the full list.', null, 'document.filename_normalized|group', 'open', '2026-07-03'),
  ('d0d0d0d0-6356-e6da-0631-a36b40f33e23', 'd0d0d0d0-5372-5840-7746-6bcbfe1a7058', 'timeliness.late_entry', 'info', 'Weld W-0001 was entered 3 business days past its standard', 'Work dated 2025-06-02, due in the book by 2025-06-03 under FDS-JBMP-001 §8.1, entered 2025-06-06. The record stands as entered — §8.3 requires a late entry to be accurate and flagged, never back-dated. This is the first of 3; open the finding for the full list.', '12', 'timeliness.late_entry|group', 'open', '2026-07-04')
